  async function verifyAdmin(){

    const {
      data: sessionData,
      error: sessionError
    } =
      await supabaseClient.auth.getSession();

    if(sessionError){
      showLogin();
      return false;
    }

    const session =
      sessionData &&
      sessionData.session;

    if(!session){
      showLogin();
      return false;
    }

    const {
      data,
      error
    } =
      await supabaseClient.rpc(
        "is_site_admin"
      );

    if(error){
      console.error("MA7ALAK ADMIN: is_site_admin check failed:", error);

      showLogin();

      setStatus(
        loginStatus,
        "Could not verify admin access. Please try again.",
        "error"
      );

      return false;
    }

    if(data !== true){
      showLogin();

      setStatus(
        loginStatus,
        "This account is not a Ma7alak site admin.",
        "error"
      );

      return false;
    }

    showDashboard(
      session.user &&
      session.user.email
    );

    await loadExistingDirectoryValues();
    await loadManagedShops();
    await loadAdminActivity();

    // Tell merged admin tools that the SAME admin session is verified and ready.
    window.dispatchEvent(new CustomEvent("ma7alak:admin-ready"));

    return true;
  }


  async function loadExistingDirectoryValues(){

    const {
      data,
      error
    } =
      await supabaseClient
        .from("shop_profiles")
        .select(
          "area,category,category_name"
        )
        .eq("is_active", true);

    if(error){
      console.warn(
        "Could not load existing filters:",
        error
      );
      return;
    }

    const areas =
      Array.from(
        new Set(
          (data || [])
            .map(row => normalizedText(row.area))
            .filter(Boolean)
        )
      ).sort(
        (a,b) => a.localeCompare(b)
      );

    const categoriesMap =
      new Map();

    (data || []).forEach(row => {

      const category =
        normalizedText(row.category);

      if(!category){
        return;
      }

      const display =
        normalizedText(row.category_name);

      if(!categoriesMap.has(category)){
        categoriesMap.set(
          category,
          display
        );
      }
    });


    areaList.innerHTML =
      areas
        .map(area => {
          return (
            '<option value="' +
            escapeHtml(area) +
            '"></option>'
          );
        })
        .join("");


    categoryList.innerHTML =
      Array.from(categoriesMap.entries())
        .sort(
          (a,b) => a[0].localeCompare(b[0])
        )
        .map(([category, label]) => {

          const optionLabel =
            label
              ? ' label="' + escapeHtml(label) + '"'
              : "";

          return (
            '<option value="' +
            escapeHtml(category) +
            '"' +
            optionLabel +
            '></option>'
          );
        })
        .join("");
  }


