  async function toggleNewBadge(shop){
    const current = shop.directory_options && typeof shop.directory_options === "object" ? shop.directory_options : {};
    const next = { ...current, badge:/^new$/i.test(normalizedText(current.badge)) ? null : "NEW" };
    const { error } = await supabaseClient
      .from("shop_profiles")
      .update({ directory_options:next })
      .eq("shop_slug", shop.shop_slug);
    if(error) throw error;
    shop.directory_options = next;
    renderManagedShops();
    await logAdminActivity(next.badge ? "shop_marked_new" : "shop_new_removed", shop.shop_slug, { shop_name:shop.shop_name || shop.shop_slug });
    loadAdminActivity();
  }


  manageShopList.addEventListener("click", async function(event){

    const button = event.target.closest("button[data-action]");
    if(!button) return;

    const card = button.closest(".ma-admin-shop-item");
    if(!card) return;

    const slug = card.dataset.slug;
    const shop = getManagedShop(slug);
    if(!shop) return;

    const action = button.dataset.action;

    if(action === "edit"){
      openEditShop(shop);
      return;
    }

    if(action === "owner"){
      openUnifiedOwnerAccess(shop);
      return;
    }

    if(action === "view"){
      const target = normalizedText(shop.shop_url) || ("https://ma7alak.com/" + encodeURIComponent(slug));
      window.open(target, "_blank", "noopener");
      return;
    }

    if(action === "gallery"){
      openGalleryManager(shop);
      return;
    }

    if(action === "video"){
      openVideoManager(shop);
      return;
    }

    if(action === "reels"){
      openReelsManager(shop);
      return;
    }

    button.disabled = true;

    try{

      if(action === "new"){
        await toggleNewBadge(shop);
        return;
      }

      if(action === "active"){

        if(!shop.is_active){
          const completeness = getShopCompleteness(shop);

          if(!completeness.ready){
            setStatus(
              manageStatus,
              'Cannot activate "' + (shop.shop_name || slug) + '" yet. ' + completenessMessage(completeness) + '.',
              "error"
            );
            return;
          }
        }

        await updateShopFlag(slug, "is_active", !shop.is_active);
        await loadExistingDirectoryValues();
        return;
      }

      if(action === "featured"){
        await updateShopFlag(slug, "featured", !shop.featured);
        return;
      }

      if(action === "delete"){

        const confirmed = window.confirm(
          'Delete "' + (shop.shop_name || slug) + '" from shop_profiles?\\n\\nThis does NOT delete its owner account or Story media.'
        );

        if(!confirmed) return;

        const { error } = await supabaseClient
          .from("shop_profiles")
          .delete()
          .eq("shop_slug", slug);

        if(error) throw error;

        if(editOriginalSlug.value === slug){
          closeEditShop();
        }

        await logAdminActivity(
          "shop_deleted",
          slug,
          { shop_name: shop.shop_name || slug }
        );
        loadAdminActivity();

        await loadManagedShops();
        await loadExistingDirectoryValues();
      }

    }catch(error){
      setStatus(manageStatus, error.message || "Action failed.", "error");
    }finally{
      button.disabled = false;
    }
  });


